-- SPEC-211: classroom quizzes, sessions, independent attendance, and answer history.
-- All IDs are generated by Prisma (`cuid()`), so these tables intentionally have
-- no database-side ID default. Apply via the approved database release workflow.

CREATE TABLE "quiz_courses" (
  "id" TEXT NOT NULL,
  "owner_id" TEXT NOT NULL,
  "title" VARCHAR(120) NOT NULL,
  "group_name" VARCHAR(80) NOT NULL DEFAULT 'General',
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "quiz_courses_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "quiz_courses_owner_id_fkey" FOREIGN KEY ("owner_id")
    REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE "quiz_enrollments" (
  "id" TEXT NOT NULL,
  "course_id" TEXT NOT NULL,
  "account_user_id" TEXT,
  "student_code" VARCHAR(32) NOT NULL,
  "source" VARCHAR(16) NOT NULL DEFAULT 'GUEST',
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "quiz_enrollments_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "quiz_enrollments_course_id_fkey" FOREIGN KEY ("course_id")
    REFERENCES "quiz_courses"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "quiz_enrollments_account_user_id_fkey" FOREIGN KEY ("account_user_id")
    REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE
);

CREATE TABLE "quiz_meetings" (
  "id" TEXT NOT NULL,
  "course_id" TEXT NOT NULL,
  "class_date" DATE NOT NULL,
  "class_start_time" VARCHAR(5),
  "time_zone" VARCHAR(48) NOT NULL DEFAULT 'America/Bogota',
  "late_after_minutes" INTEGER,
  "attendance_locked_at" TIMESTAMP(3),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "quiz_meetings_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "quiz_meetings_course_id_fkey" FOREIGN KEY ("course_id")
    REFERENCES "quiz_courses"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "quiz_meetings_late_after_minutes_check" CHECK (
    "late_after_minutes" IS NULL OR "late_after_minutes" BETWEEN 0 AND 240
  )
);

CREATE TABLE "quiz_sets" (
  "id" TEXT NOT NULL,
  "course_id" TEXT NOT NULL,
  "title" VARCHAR(160) NOT NULL,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "quiz_sets_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "quiz_sets_course_id_fkey" FOREIGN KEY ("course_id")
    REFERENCES "quiz_courses"("id") ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE "quiz_questions" (
  "id" TEXT NOT NULL,
  "quiz_set_id" TEXT NOT NULL,
  "order" INTEGER NOT NULL,
  "kind" VARCHAR(20) NOT NULL DEFAULT 'SINGLE_CHOICE',
  "topic" VARCHAR(80) NOT NULL DEFAULT '',
  "difficulty" VARCHAR(16) NOT NULL DEFAULT 'INTERMEDIATE',
  "prompt" VARCHAR(500) NOT NULL,
  "options" JSONB NOT NULL,
  "correct_option_index" INTEGER NOT NULL,
  "explanation" VARCHAR(1000) NOT NULL DEFAULT '',
  "seconds" INTEGER NOT NULL DEFAULT 30,
  CONSTRAINT "quiz_questions_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "quiz_questions_quiz_set_id_fkey" FOREIGN KEY ("quiz_set_id")
    REFERENCES "quiz_sets"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "quiz_questions_unique_order" UNIQUE ("quiz_set_id", "order"),
  CONSTRAINT "quiz_questions_valid_seconds" CHECK ("seconds" BETWEEN 10 AND 180)
);

CREATE TABLE "quiz_sessions" (
  "id" TEXT NOT NULL,
  "meeting_id" TEXT NOT NULL,
  "quiz_set_id" TEXT NOT NULL,
  "join_code" VARCHAR(6) NOT NULL,
  "status" VARCHAR(16) NOT NULL DEFAULT 'LOBBY',
  "question_index" INTEGER NOT NULL DEFAULT -1,
  "state_version" INTEGER NOT NULL DEFAULT 0,
  "speed_bonus" BOOLEAN NOT NULL DEFAULT false,
  "projection_token_hash" VARCHAR(64),
  "question_started_at" TIMESTAMP(3),
  "question_ends_at" TIMESTAMP(3),
  "started_at" TIMESTAMP(3),
  "finished_at" TIMESTAMP(3),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "quiz_sessions_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "quiz_sessions_meeting_id_fkey" FOREIGN KEY ("meeting_id")
    REFERENCES "quiz_meetings"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "quiz_sessions_quiz_set_id_fkey" FOREIGN KEY ("quiz_set_id")
    REFERENCES "quiz_sets"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT "quiz_sessions_join_code_key" UNIQUE ("join_code"),
  CONSTRAINT "quiz_sessions_join_code_check" CHECK ("join_code" ~ '^\d{6}$')
);

CREATE TABLE "quiz_participants" (
  "id" TEXT NOT NULL,
  "session_id" TEXT NOT NULL,
  "enrollment_id" TEXT NOT NULL,
  "nickname" VARCHAR(24) NOT NULL,
  "initial_access" VARCHAR(8) NOT NULL,
  "resume_token_hash" VARCHAR(64),
  "score" INTEGER NOT NULL DEFAULT 0,
  "joined_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "quiz_participants_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "quiz_participants_session_id_fkey" FOREIGN KEY ("session_id")
    REFERENCES "quiz_sessions"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "quiz_participants_enrollment_id_fkey" FOREIGN KEY ("enrollment_id")
    REFERENCES "quiz_enrollments"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "quiz_participants_unique_enrollment" UNIQUE ("session_id", "enrollment_id"),
  CONSTRAINT "quiz_participants_access_check" CHECK ("initial_access" IN ('ACCOUNT', 'GUEST'))
);

CREATE TABLE "quiz_answers" (
  "id" TEXT NOT NULL,
  "participant_id" TEXT NOT NULL,
  "question_id" TEXT NOT NULL,
  "request_id" UUID NOT NULL,
  "option_index" INTEGER NOT NULL,
  "correct" BOOLEAN NOT NULL,
  "points" INTEGER NOT NULL,
  "answered_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "quiz_answers_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "quiz_answers_participant_id_fkey" FOREIGN KEY ("participant_id")
    REFERENCES "quiz_participants"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "quiz_answers_question_id_fkey" FOREIGN KEY ("question_id")
    REFERENCES "quiz_questions"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "quiz_answers_unique_response" UNIQUE ("participant_id", "question_id"),
  CONSTRAINT "quiz_answers_request_id_key" UNIQUE ("request_id")
);

CREATE TABLE "quiz_attendance" (
  "id" TEXT NOT NULL,
  "meeting_id" TEXT NOT NULL,
  "enrollment_id" TEXT NOT NULL,
  "student_code" VARCHAR(32) NOT NULL,
  "nickname" VARCHAR(24) NOT NULL,
  "initial_access" VARCHAR(8) NOT NULL,
  "status" VARCHAR(16) NOT NULL DEFAULT 'PRESENT',
  "arrived_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "quiz_attendance_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "quiz_attendance_meeting_id_fkey" FOREIGN KEY ("meeting_id")
    REFERENCES "quiz_meetings"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "quiz_attendance_enrollment_id_fkey" FOREIGN KEY ("enrollment_id")
    REFERENCES "quiz_enrollments"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "quiz_attendance_unique_student" UNIQUE ("meeting_id", "enrollment_id"),
  CONSTRAINT "quiz_attendance_status_check" CHECK ("status" IN ('PRESENT', 'LATE', 'EXCUSED'))
);

CREATE TABLE "quiz_attendance_audit" (
  "id" TEXT NOT NULL,
  "attendance_id" TEXT NOT NULL,
  "editor_id" TEXT NOT NULL,
  "reason" VARCHAR(500) NOT NULL,
  "before" JSONB NOT NULL,
  "after" JSONB NOT NULL,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "quiz_attendance_audit_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "quiz_attendance_audit_attendance_id_fkey" FOREIGN KEY ("attendance_id")
    REFERENCES "quiz_attendance"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "quiz_attendance_audit_editor_id_fkey" FOREIGN KEY ("editor_id")
    REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);

CREATE INDEX "quiz_courses_owner_id_created_at_idx" ON "quiz_courses"("owner_id", "created_at");
CREATE UNIQUE INDEX "quiz_enrollments_course_id_student_code_key" ON "quiz_enrollments"("course_id", "student_code");
CREATE UNIQUE INDEX "quiz_enrollments_course_id_account_user_id_key" ON "quiz_enrollments"("course_id", "account_user_id");
CREATE INDEX "quiz_enrollments_account_user_id_idx" ON "quiz_enrollments"("account_user_id");
CREATE INDEX "quiz_meetings_course_id_class_date_idx" ON "quiz_meetings"("course_id", "class_date");
CREATE INDEX "quiz_sets_course_id_created_at_idx" ON "quiz_sets"("course_id", "created_at");
CREATE INDEX "quiz_sessions_meeting_id_created_at_idx" ON "quiz_sessions"("meeting_id", "created_at");
CREATE INDEX "quiz_participants_session_id_score_idx" ON "quiz_participants"("session_id", "score");
CREATE INDEX "quiz_participants_resume_token_hash_idx" ON "quiz_participants"("resume_token_hash");
CREATE INDEX "quiz_attendance_meeting_id_arrived_at_idx" ON "quiz_attendance"("meeting_id", "arrived_at");
CREATE INDEX "quiz_attendance_audit_attendance_id_created_at_idx" ON "quiz_attendance_audit"("attendance_id", "created_at");
